(()=>{
const S=Site,D=FrameData,{esc,art,link,button,sectionHead,faq,crumbs}=S;
const toolCard=t=>link(`<div class="tool-card-top"><span class="tool-icon">${t.icon}</span><span class="micro-tag">${t.stage==='P2'?'高级演示':'示例可体验'} ↗</span></div><h3>${t.title}</h3><p>${t.desc}</p><div class="tool-card-foot">${t.group}<span>打开工具 →</span></div>`,'/tools/'+t.id,'tool-card');
const caseCard=c=>link(`<div class="case-picture">${art(c.art,c.title)}<span class="play-circle">▷</span><span class="picture-label">${c.seconds}s · 视频示例</span></div><div class="case-copy"><span class="eyebrow">${c.tag} / ORIGINAL STORY</span><h3>${c.title} <span>↗</span></h3><p>${c.subtitle}</p></div>`,'/showcase/'+c.id,'case-card');
const templateCard=t=>link(`<div class="template-picture">${art(t.art,t.title)}<span>${t.type}模板</span></div><div class="case-copy"><h3>${t.title}</h3><p>${t.desc}</p></div>`,'/templates/'+t.id,'case-card');
const articleCard=a=>link(`<div class="article-picture">${art(a.art,a.title)}</div><div class="case-copy"><span class="eyebrow">${a.category} · ${a.time}</span><h3>${a.title}</h3><p>用清晰的步骤，完成下一次创作。 →</p></div>`,'/resources/'+a.id,'case-card');
const cta=()=>`<section class="closing-cta"><span class="eyebrow">YOUR STORY STARTS HERE</span><h2>下一格，会发生什么？</h2><p>带着你的角色和故事，从这里开始。</p><div class="button-row">${link('开始一个新故事 ↗','/app/new','button primary')}${link('先体验免费工具','/tools','button ghost')}</div></section>`;
function home(){S.pageTitle='让你的故事，走出画格';return `<main><section class="home-hero"><div class="hero-grid-lines"></div><div class="hero-copy"><span class="hero-label"><b></b> FOR YOUR NEXT CHAPTER</span><h1>让你的故事，<br><em>走出画格。</em></h1><p>从第一个角色，到一整章漫画，再到会动的故事。<br>你的想象，在同一个创作空间里继续生长。</p><div class="button-row">${link('开始创作 <span>↗</span>','/app/new','button primary large')}${link('▷ 探索示例作品','/showcase/rain','button ghost large')}</div><div class="hero-note"><span>同一个角色</span><i>·</i><span>每一格可编辑</span><i>·</i><span>作品与你同在</span></div></div><div class="hero-art"><div class="hero-floating-note"><span>CHAPTER 01</span><strong>有些重逢，是故事重新开始。</strong><small>雨停之前 / 原创演示作品</small></div><div class="hero-panel panel-back">${art(0,'雨中的旧书店')}<span>01 / THE SETTING</span></div><div class="hero-panel panel-front">${art(1,'林夏在雨中重逢')}<div class="hero-dialogue">七年了，<br>你还记得我吗？</div><span>02 / A FAMILIAR FACE</span></div><div class="hero-panel panel-side">${art(2,'陈序在书店')}<span>03 / THE REUNION</span></div><div class="hero-motion-pill"><span>▷</span><div>从漫画，到视频<small>角色与画风，一路保持一致</small></div><b>↗</b></div></div></section><div class="manifesto-strip"><span>为独立作者与小型工作室而设计</span><b>WEBTOON</b><i>+</i><b>MOTION COMIC</b><i>+</i><b>YOUR ORIGINAL WORLD</b></div><section class="section wrap">${sectionHead('ONE STORY, MANY POSSIBILITIES','每个故事，都有自己的入口。','带着灵感来，也可以带着已经画好的世界来。')}<div class="entry-grid">${D.sources.map((x,i)=>link(`<span class="entry-no">0${i+1}</span><span class="entry-icon">${x.icon}</span><h3>${x.title}</h3><p>${x.desc}</p><span class="entry-arrow">开始 →</span>`,'/app/new?source='+x.id,'entry-card')).join('')}</div></section><section class="section story-section wrap"><div>${sectionHead('CREATE ONCE. KEEP CREATING.','同一个世界，<br>贯穿每一种表达。','角色、场景、画风与声音始终相连。修改一格，只重做受影响的部分。')}<div class="story-feature-list">${[['01','先讲好故事','把创意、小说或故事整理成你确认的章节分镜。'],['02','让每一格都像你的作品','锁定角色与画风，通过局部修改保留你满意的画面。'],['03','让情绪开始流动','稳定运镜承载叙事，关键动作再由你选择增强。']].map(([n,t,d])=>`<div><span>${n}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div>${link('了解一体化创作流程 ↗','/product','text-link')}</div><div class="story-demo"><div class="demo-toolbar"><span><b></b> 雨停之前 / 统一资产</span><small>STORY WORKSPACE</small></div><div class="demo-art">${art(6,'林夏与陈序共伞')}<span class="demo-tag">角色身份已绑定 ✓</span><span class="demo-subtitle">这一次，一起走吧。</span></div><div class="demo-assets">${[1,2,0].map((v,i)=>`<div>${art(v)}<span>${['林夏 v2','陈序 v1','书店 v1'][i]}</span><b>✓</b></div>`).join('')}</div><div class="demo-timeline">${[0,1,2,3,6,7,8].map(v=>art(v)).join('')}</div></div></section><section class="section tools-home"><div class="wrap">${sectionHead('SMALL TOOLS, BIG IDEAS','先从一个小工具，找到创作的手感。','免登录体验示例。喜欢的结果，可以直接带进你的项目。',link('探索全部创作工具 ↗','/tools','text-link'))}<div class="tool-grid">${D.tools.filter(t=>!t.hidden).slice(0,4).map(toolCard).join('')}</div></div></section><section class="section wrap">${sectionHead('STORIES IN THE MAKING','看看故事，可以长成什么样。','以下为原创示例项目，用于展示创作与交付流程。',link('查看全部案例 ↗','/showcase','text-link'))}<div class="case-grid">${D.cases.map(caseCard).join('')}</div></section><section class="section principles wrap"><div><span>◎</span><h3>角色，是故事的锚点。</h3><p>资产版本随项目保留，画面之间的联系始终清楚。</p></div><div><span>↶</span><h3>好创作，留有余地。</h3><p>候选需要你主动采用，每一次参数修改都有迹可循。</p></div><div><span>◒</span><h3>成本，不用靠猜。</h3><p>增强前确认预计用量，保留能交付的稳定底稿。</p></div></section><section class="section faq-section wrap">${sectionHead('A FEW THINGS TO KNOW','开始之前，你可能想知道。')}${faq()}</section>${cta()}</main>`;}
const features={webtoon:{title:'你的故事，值得一格一格画出来。',desc:'从灵感、小说到完整故事，先确认叙事，再让角色进入画面。',art:1,tag:'WEBTOON CREATION',source:'idea',steps:['整理标准章节内容','确认角色、场景与画风','逐格生成和局部修正','编排阅读节奏并导出'],points:['角色与服装共享版本，连续画面保持一致。','对白框、旁白和音效字与画面分开编辑。','已经满意的画面，不必因为一个表情重新生成。']},'motion-comic':{title:'不止让画面动起来，让情绪有了节奏。',desc:'运镜、对白、字幕和有限动画构成稳定底稿。关键动作，交给你选择的增强候选。',art:6,tag:'MOTION COMIC PRODUCTION',source:'comic',steps:['导入或复用漫画分格','规划镜头时长与运镜','对比关键动作增强候选','检查音画与字幕，审批导出'],points:['稳定动画不被增强覆盖，失败也能继续交付。','单镜头编辑，保留每次参数和采用记录。','漫画修改后，确认受影响镜头再局部同步。']},studio:{title:'一个工作室的世界，应该记得每个细节。',desc:'项目、资产、版本、质量和预算在同一处。让连续生产更清晰。',art:0,tag:'STUDIO WORKFLOW',source:'script',steps:['建立共享资产库','按章节安排任务','逐项审查版本差异','确认费用与交付版本'],points:['角色、道具与服装的引用范围一目了然。','任务失败可以定位和重试，不需要重来整章。','团队批注与审批为高级交互演示，真实服务按阶段建设。']}};
function feature(id){const f=features[id];if(!f)return notFound();S.pageTitle=['webtoon','motion-comic','studio'].includes(id)?f.tag:'产品功能';return `<main class="wrap"><section class="feature-hero">${crumbs([['产品','/product'],[f.tag,null]])}<div class="feature-hero-grid"><div><span class="eyebrow">${f.tag}</span><h1>${f.title}</h1><p>${f.desc}</p><div class="button-row">${link('从这里开始 ↗','/app/new?source='+f.source,'button primary')}${link('体验示例','/app/editor/rain/ch1?step='+ (id==='webtoon'?'comic':'motion'),'button ghost')}</div></div><div class="feature-art">${art(f.art,f.tag)}<span class="feature-art-label">ONE STORY / ONE WORKSPACE</span></div></div></section><section class="section">${sectionHead('A CLEAR CREATIVE FLOW','从想法，到可交付的作品。')}<div class="process-grid">${f.steps.map((t,i)=>`<div><span>0${i+1}</span><h3>${t}</h3><p>${f.points[i%3]}</p></div>`).join('')}</div></section><section class="section split-feature"><div class="feature-art">${art(id==='webtoon'?3:8,'局部编辑与版本示例')}</div><div><span class="eyebrow">EDITABLE BY DESIGN</span><h2>创作不是一次抽卡。<br>每一步，都可以继续打磨。</h2>${f.points.map(p=>`<p class="check-point">✓ ${p}</p>`).join('')}${link('打开工作台看看 →','/app/editor/rain/ch1','text-link')}</div></section><section class="section">${sectionHead('TOOLS THAT CONNECT','相关工具，直接连到你的项目。')}<div class="tool-grid three">${D.tools.filter(t=>!t.hidden).filter(t=>id==='webtoon'?['oc-sheet','lettering','colorize'].includes(t.id):id==='studio'?t.group==='工作室效率':['comic-to-motion','motion-quality','pngtuber'].includes(t.id)).map(toolCard).join('')}</div></section><section class="section">${faq(D.faqs.slice(0,3))}</section>${cta()}</main>`;}
function product(){S.pageTitle='一体化创作空间';return `<main class="wrap"><section class="page-hero centered"><span class="eyebrow">COMIC + ANIMATION, IN ONE PROJECT</span><h1>不用把故事，<br>散落在不同工具里。</h1><p>漫画是视觉与叙事的真源，视频沿用同一组角色、场景和声音。<br>你只需要继续创作。</p>${link('打开示例工作空间 ↗','/app','button primary')}</section><div class="product-world">${[0,1,6,8].map((v,i)=>`<div>${art(v)}<span>${['故事与角色','漫画分格','动态镜头','交付与推广'][i]}</span></div>`).join('')}</div><section class="section">${sectionHead('THREE WAYS TO KEEP CREATING','从创作，到连续生产。')}<div class="tool-grid three">${Object.entries(features).map(([id,f])=>link(`<span class="eyebrow">${f.tag}</span><h3>${{webtoon:'漫画创作','motion-comic':'视频制作',studio:'工作室生产'}[id]}</h3><p>${f.desc}</p><span class="text-link">了解更多 ↗</span>`,'/features/'+id,'tool-card')).join('')}</div></section><section class="section mode-comparison"><div><span class="eyebrow">QUICK MODE</span><h2>快速模式</h2><p>先看到一个完整方向，再决定如何深入。自动组织角色草案与分镜，适合验证灵感。</p>${link('快速试一个故事 →','/app/new?mode=quick','button ghost')}</div><div><span class="eyebrow">STUDIO MODE</span><h2>工作室模式</h2><p>先确认角色、场景、画风和分镜，再批量生成。适合持续制作自己的世界。</p>${link('建立一个创作项目 →','/app/new?mode=studio','button primary')}</div></section>${cta()}</main>`;}
function catalog(kind){const isCase=kind==='showcase',isTemplate=kind==='templates';S.pageTitle=isCase?'示例作品':isTemplate?'创作模板':'创作指南';const data=isCase?D.cases:isTemplate?D.templates:D.articles;return `<main class="wrap"><section class="page-hero"><span class="eyebrow">${isCase?'STORIES WORTH TELLING':isTemplate?'A GOOD PLACE TO START':'FIELD NOTES FOR CREATORS'}</span><h1>${isCase?'从这些故事里，<br>看见你的下一种可能。':isTemplate?'给灵感，一个起点。':'把故事做出来的那些方法。'}</h1><p>${isCase?'原创演示作品，展示从角色与漫画到视频的完整关系。':isTemplate?'为情绪、节奏和角色准备的模板。带进项目后，每个细节依然可编辑。':'从第一格漫画到连续制作，让创作经验成为可以复用的方法。'}</p></section>${isTemplate?`<div class="filter-row">${['全部','运镜','漫画','角色','推广'].map(v=>button(v,'template-filter','filter '+(S.ui.templateType===v?'selected':''),`data-value="${v}"`)).join('')}</div>`:''}<div class="case-grid" id="catalog-grid">${data.filter(v=>!isTemplate||S.ui.templateType==='全部'||v.type===S.ui.templateType).map(isCase?caseCard:isTemplate?templateCard:articleCard).join('')}</div>${kind==='resources'?`<section class="section">${link('查看产品更新记录 →','/resources/updates','text-link')}</section>`:''}${cta()}</main>`;}
function caseDetail(id){const c=D.cases.find(x=>x.id===id);if(!c)return notFound();S.pageTitle=c.title+' · 示例作品';return `<main class="wrap"><section class="case-detail-head">${crumbs([['示例作品','/showcase'],[c.title,null]])}<div class="section-head"><div><span class="eyebrow">ORIGINAL DEMO / ${c.tag}</span><h1>${c.title}</h1><p>${c.subtitle}</p></div>${button('复制示例到我的项目 ↗','copy-case','button primary',`data-id="${c.id}"`)}</div></section><div class="showcase-view"><div class="showcase-main" id="case-stage">${art(c.art,c.title)}<div class="showcase-overlay"><span>ORIGINAL STORY / ${c.shots} PANELS</span><h2>${c.title}</h2><p>${c.subtitle}</p>${button('▷ 播放运镜示意','case-play','button glass')}</div></div><aside><span class="eyebrow">PROJECT NOTES</span><h3>一个世界，两种表达。</h3><p>${c.shots} 格漫画 · ${c.seconds} 秒视频<br>角色与场景共享资产版本</p><div class="button-row">${button('视频','case-mode','filter selected','data-value="motion"')}${button('漫画','case-mode','filter','data-value="comic"')}</div><div class="showcase-thumbs">${[1,2,7].map(i=>art(i)).join('')}</div><small>原创 SVG 示例，不是模型生成效果或真实客户作品。</small></aside></div><section class="section">${sectionHead('HOW THE STORY WAS MADE','画面之外，创作有迹可循。')}<div class="process-grid">${['锁定角色与雨日画风','确认分镜与对白','稳定底稿与关键增强','最终审查与版本交付'].map((t,i)=>`<div><span>0${i+1}</span><h3>${t}</h3><p>在同一个项目中完成，已有版本和候选始终保留。</p></div>`).join('')}</div></section><section class="section">${sectionHead('CONTINUE WITH THESE TOOLS','把喜欢的方式，带进自己的故事。')}<div class="tool-grid three">${D.tools.filter(t=>!t.hidden).slice(1,4).map(toolCard).join('')}</div></section></main>`;}
function templateDetail(id){const t=D.templates.find(x=>x.id===id);if(!t)return notFound();S.pageTitle=t.title;return `<main class="wrap"><section class="feature-hero">${crumbs([['模板','/templates'],[t.title,null]])}<div class="feature-hero-grid"><div><span class="eyebrow">${t.type} / EDITABLE TEMPLATE</span><h1>${t.title}</h1><p>${t.desc} 采用后可以更换画面、对白和节奏，保留自己的叙事方式。</p>${link('使用这个模板 ↗',t.type==='推广'?'/app/promote/rain':'/app/new?template='+t.id,'button primary')}<ul class="plain-list"><li>✓ 使用本地示例，所有参数可修改</li><li>✓ 模板选择会保留在新项目草稿中</li><li>✓ 不包含第三方作品或真实模型调用</li></ul></div><div class="feature-art ${t.type==='运镜'?'gentle-preview':''}">${art(t.art,t.title)}</div></div></section><section class="section">${sectionHead('MAKE IT YOURS','三步，变成你的作品。')}<div class="process-grid three">${['选择或导入你的画面','替换角色与对白','确认节奏后加入章节'].map((x,i)=>`<div><span>0${i+1}</span><h3>${x}</h3><p>不满意的地方局部调整，已有版本保留。</p></div>`).join('')}</div></section>${cta()}</main>`;}
function pricing(){S.pageTitle='定价与用量';const annual=(S.ui.priceCycle||S.state.cycle)==='yearly';return `<main class="wrap"><section class="page-hero centered"><span class="eyebrow">SPACE FOR YOUR NEXT CHAPTER</span><h1>为创作空间付费，<br>每次生成，都心中有数。</h1><p>订阅用于工作空间与制作能力；外部模型按实际用量单独核算。<br>以下是产品定价演示，所有选择均不会扣款。</p><div class="period-toggle">${button('按月','price-cycle',!annual?'selected':'','data-value="monthly"')}${button('按年 · 示例优惠','price-cycle',annual?'selected':'','data-value="yearly"')}</div></section><div class="pricing-grid">${[{name:'Free',tag:'从一个小工具开始',price:0,items:['匿名体验示例工具','一个演示工作空间','示例作品与模板','本机结果下载']},{name:'Creator',tag:'让自己的故事持续生长',price:annual?15:19,items:['独立作者的项目与资产','漫画与视频一体制作','局部编辑与版本历史','预算与生成记录']},{name:'Studio',tag:'为一个团队的世界而设计',price:annual?47:59,items:['工作室项目与共享资产','成员与席位配置演示','差异审查与批量交付','质量、任务和费用面板']}].map((p,i)=>`<article class="price-card ${i===1?'recommended':''}">${i===1?'<span class="recommend-tag">为独立创作者推荐</span>':''}<span class="eyebrow">${p.name.toUpperCase()}</span><h3>${p.tag}</h3><div class="price">$${p.price}<small>/ 月${annual?' · 按年结算示意':''}</small></div><p class="muted">${i?'模型用量另计，调用前显示预估':'无需填写付款信息'}</p>${button(i?'体验 '+p.name+' 方案':'开始免费体验','choose-plan','button '+(i===1?'primary':'ghost')+' full',`data-plan="${p.name}"`)}<ul class="plain-list">${p.items.map(x=>`<li>✓ ${x}</li>`).join('')}</ul></article>`).join('')}</div><section class="section cost-explainer">${sectionHead('PREDICTABLE, BY DESIGN','订阅和模型用量，分开看得清。')}<div class="two-col"><div class="surface"><h3>工作空间订阅</h3><p>为资产、编辑、版本与生产组织付费。稳定动画本身不按视频模型次次抽卡。</p></div><div class="surface"><h3>模型调用费用</h3><p>分格生成、语音和关键动作增强按量记录。确认前可见预估，超预算停止新调用。</p>${link('查看订阅与用量 →','/app/billing','text-link')}</div></div></section><section class="section">${faq()}</section></main>`;}
function resource(id){if(id==='updates'){S.pageTitle='产品更新';return `<main class="wrap narrow"><section class="page-hero">${crumbs([['创作指南','/resources'],['更新记录',null]])}<h1>让创作，继续变好。</h1><p>静态原型更新记录</p></section>${[['2026.10.28','全站创作体验','官网、14 项工具、项目与资产、推广分享进入同一个原型。'],['2026.10.28','每个版本都有来处','新增参数历史、恢复为新版本、专注画布和时间线定位。'],['2026.10.27','从一章故事开始','建立漫画与视频的 M0 五步工作台。']].map(([d,t,p])=>`<article class="update-entry"><span class="eyebrow">${d}</span><h2>${t}</h2><p>${p}</p></article>`).join('')}</main>`;}const a=D.articles.find(x=>x.id===id);if(!a)return notFound();S.pageTitle=a.title;return `<main class="wrap narrow"><section class="page-hero">${crumbs([['创作指南','/resources'],[a.category,null]])}<span class="eyebrow">${a.category} · ${a.time}</span><h1>${a.title}</h1><p>帧间创作笔记 · 原型示例教程</p></section><div class="article-cover">${art(a.art,a.title)}</div><article class="prose"><p>一个完整的创作流程，应该让你把注意力留给故事本身。这篇指南通过《雨停之前》演示如何安排每一步，并在修改时保留已有成果。</p>${a.steps.map((step,i)=>`<section><span class="eyebrow">STEP 0${i+1}</span><h2>${step}</h2><p>${['先明确这一章希望观众感受到什么。用简短的场景和对白表达剧情目标，避免在未确认故事前批量生成画面。','选择已经确认的参考和资产版本。对角色的发型、服装和情绪做具体约束，让后续画面有稳定依据。','将问题限制在受影响的画面与镜头内，比较候选后主动采用。旧版本继续保留，便于回退与复查。','交付前检查顺序、字幕和版本。漫画可以独立导出，也可以继续进入视频画布制作。'][i]}</p></section>`).join('')}<div class="surface"><h3>亲手试一次</h3><p>打开本地示例项目，跟着步骤体验。不会调用任何付费模型。</p>${link('打开《雨停之前》 →','/app/projects/rain','button primary')}</div></article></main>`;}
function help(){S.pageTitle='帮助中心';return `<main class="wrap"><section class="page-hero centered"><span class="eyebrow">HERE TO HELP YOU CREATE</span><h1>创作卡住了？<br>从这里，继续向前。</h1><p>选择一个问题，或在指南中寻找答案。</p></section><div class="help-categories">${[['故事与分镜','first-chapter','▤'],['角色与资产','consistent-characters','◎'],['动画与导出','stable-motion','▷'],['推广与分享','release-kit','↗']].map(([t,id,ic])=>link(`<span>${ic}</span><h3>${t}</h3><p>查看步骤指南 →</p>`,'/resources/'+id,'surface')).join('')}</div><section class="section">${faq()}</section><div class="help-contact"><h2>还没有找到答案？</h2><p>可以记录使用问题或原型反馈，保存在本机。</p>${button('填写反馈','support','button primary')}</div></main>`;}
function legal(id){const titles={privacy:'隐私与数据',copyright:'商业使用与版权',terms:'服务条款',content:'内容与声音政策'};S.pageTitle=titles[id]||'使用政策';return `<main class="wrap narrow"><section class="page-hero"><span class="eyebrow">TRANSPARENCY FIRST</span><h1>${S.pageTitle}</h1><p>产品政策草案展示 · 非正式运营协议</p></section><div class="policy-notice">此页用于评审正式产品应披露的信息，不代表已经上线的服务承诺。本原型不收集真实账户凭证、不调用模型、不执行支付或对外发布。</div><article class="prose">${[['本机演示数据','演示项目、设置和工具结果保存在当前浏览器。你可以在个人中心中备份或清除这些数据。上传素材仅在本机预览，不发送到外部供应商。'],['素材与生成结果的权利','用户应持有上传素材的使用权。正式服务需逐项说明供应商许可、商业使用范围、版权申诉、DMCA 处理和侵权投诉入口。演示插画为本地原创 SVG。'],['数据使用与保留','正式上线前需明确素材是否用于训练、处理目的、保存期限、删除流程、供应商处理范围和 GDPR 数据导出。原型不暗示已经完成这些运营能力。'],['声音与内容边界','原型不克隆真实人物声音。正式服务需明确声音授权、未成年人、NSFW 和违法内容边界，不能以订阅购买替代素材或声音授权。'],['订阅、费用与终止','页面金额和套餐为示例，操作不会形成合同或扣款。正式服务的结算、退款、取消、额度和供应商失败计费须以正式协议为准。']].map(([t,p])=>`<section><h2>${t}</h2><p>${p}</p></section>`).join('')}</article><div class="button-row">${link('隐私','/legal/privacy','button ghost')}${link('版权','/legal/copyright','button ghost')}${link('内容政策','/legal/content','button ghost')}</div></main>`;}
function notFound(){S.pageTitle='页面未找到';return `<main class="wrap">${S.empty('这一页还没有故事。','你可以回到首页，或继续探索创作工具。','返回首页','/')}</main>`;}
S.public={toolCard,caseCard,templateCard,render(c){const [a,b]=c.parts;if(a===''||c.path==='/')return home();if(a==='product')return product();if(a==='features')return feature(b);if(['showcase','templates','resources'].includes(a)){if(!b)return catalog(a);return a==='showcase'?caseDetail(b):a==='templates'?templateDetail(b):resource(b);}if(a==='pricing')return pricing();if(a==='help')return help();if(a==='legal')return legal(b);return notFound();},onClick(action,el){if(action==='template-filter'){S.ui.templateType=el.dataset.value;S.render();return true;}if(action==='price-cycle'){S.state.cycle=el.dataset.value;S.save();S.render();return true;}if(action==='choose-plan'){S.modal('体验 '+el.dataset.plan+' 方案',`<p>将把本地演示账户切换为 <strong>${esc(el.dataset.plan)}</strong>。这不是购买，不会扣款或创建真实订阅。</p>`,`<button class="button ghost" data-act="close">取消</button><button class="button primary" data-act="confirm-plan" data-plan="${el.dataset.plan}">确认演示方案</button>`);return true;}if(action==='case-play'){const stage=S.$('#case-stage');stage.classList.toggle('is-playing');el.textContent=stage.classList.contains('is-playing')?'Ⅱ 暂停运镜示意':'▷ 播放运镜示意';return true;}if(action==='case-mode'){S.$$('.showcase-view [data-act="case-mode"]').forEach(b=>b.classList.toggle('selected',b===el));S.$('#case-stage').classList.toggle('comic-preview',el.dataset.value==='comic');S.toast(el.dataset.value==='comic'?'已切换漫画画面预览。':'已切换视频运镜示意。');return true;}return false;}};
})();
